(2374695, 328708, 49916, '<td valign="top">Out of focus and grainy.</td>', 'Out of focus and grainy.', '2006-05-03 01:21:59.000000', NULL, 1),
(2374700, 328577, 42826, '<td valign="top">I am going to comment on this...cause that''s just crazy...good thing you are able to do it with a slow shutter speed huh!  Anyways very creative photo!  I am giving you a 10!</td>', 'I am going to comment on this...cause that''s just crazy...good thing you are able to do it with a slow shutter speed huh!  Anyways very creative photo!  I am giving you a 10!', '2006-05-03 01:23:42.000000', NULL, 1),
