(2375628, 328862, 57229, '<td valign="top">A little overworked on the sky colours, with the horizontal lines dominating the rhythmic verticals. Nice shot half way meets the challenge.</td>', 'A little overworked on the sky colours, with the horizontal lines dominating the rhythmic verticals. Nice shot half way meets the challenge.', '2006-05-03 05:45:18.000000', NULL, 1),
(2375631, 329350, 57229, '<td valign="top">Like the subject, not so sure about the crop/composition...</td>', 'Like the subject, not so sure about the crop/composition...', '2006-05-03 05:46:02.000000', NULL, 1),
(2375637, 328759, 57229, '<td valign="top">Strong forms, although the internal form of the farthest arches is lost.</td>', 'Strong forms, although the internal form of the farthest arches is lost.', '2006-05-03 05:47:25.000000', NULL, 1),
(2375643, 329286, 58055, '<td valign="top">personally would have preferred the focus on the first key and to see less of an angle to include more of the keyboard</td>', 'personally would have preferred the focus on the first key and to see less of an angle to include more of the keyboard', '2006-05-03 05:48:38.000000', NULL, 1),
(2375644, 328950, 57229, '<td valign="top">I want in...</td>', 'I want in...', '2006-05-03 05:48:46.000000', NULL, 1),
(2375651, 329378, 58055, '<td valign="top">it looks a bit like a holiday sanp, nothing is really in focus, it may have work better to zoom in on one boat in particular making that the focal point and have the rest of the boats as background</td>', 'it looks a bit like a holiday sanp, nothing is really in focus, it may have work better to zoom in on one boat in particular making that the focal point and have the rest of the boats as background', '2006-05-03 05:50:26.000000', NULL, 1),
(2375652, 326936, 57229, '<td valign="top">I like these minimal pictures, but they''re a bit sort of ... well, I suppose they have to be lacking something or they wouldn''t be minimal, but the <i>so what?</i> bell rings here.</td>', 'I like these minimal pictures, but they''re a bit sort of ... well, I suppose they have to be lacking something or they wouldn''t be minimal, but the so what? bell rings here.', '2006-05-03 05:50:45.000000', NULL, 1),
(2375654, 327673, 58055, '<td valign="top">nice photo, I love the shadows</td>', 'nice photo, I love the shadows', '2006-05-03 05:51:07.000000', NULL, 1),
(2375662, 329422, 57229, '<td valign="top">The diagonal line of the strings add dynamic to this. I think I would prefer greater depth of field - holy grail that it is - concept is good.</td>', 'The diagonal line of the strings add dynamic to this. I think I would prefer greater depth of field - holy grail that it is - concept is good.', '2006-05-03 05:52:49.000000', NULL, 1),
