(2375667, 327783, 58055, '<td valign="top">very clever and a good photo</td>', 'very clever and a good photo', '2006-05-03 05:53:23.000000', NULL, 1),
(2375671, 327555, 57229, '<td valign="top">It was always going to be a tricky challenge to interpret, but I think this is more of a mirror image that a rhythmic one</td>', 'It was always going to be a tricky challenge to interpret, but I think this is more of a mirror image that a rhythmic one', '2006-05-03 05:54:38.000000', NULL, 1),
(2375679, 329159, 57229, '<td valign="top">Lacks dynamic imo</td>', 'Lacks dynamic imo', '2006-05-03 05:55:16.000000', NULL, 1),
(2375681, 329088, 57229, '<td valign="top">Spooky but not popping?</td>', 'Spooky but not popping?', '2006-05-03 05:55:55.000000', NULL, 1),
(2375688, 328726, 57229, '<td valign="top">There actually is rhythm here, but too much drowned in chaos, I think. Shame - there are some lovely textures.</td>', 'There actually is rhythm here, but too much drowned in chaos, I think. Shame - there are some lovely textures.', '2006-05-03 05:57:59.000000', NULL, 1),
(2375697, 329147, 57229, '<td valign="top">I''m not marching towards that. There''s a great little thing going on with the inside and outside in positive/negative complement. Wish it wasn''t cut off though.</td>', 'I''m not marching towards that. There''s a great little thing going on with the inside and outside in positive/negative complement. Wish it wasn''t cut off though.', '2006-05-03 06:00:14.000000', NULL, 1),
(2375700, 328644, 57229, '<td valign="top">More white noise than rhythm...</td>', 'More white noise than rhythm...', '2006-05-03 06:00:44.000000', NULL, 1),
(2375708, 329407, 57229, '<td valign="top">It''s a portrait to so great an extent as to detract from the effect of the rhythmic elements. I think I''d like to see her smaller for the context, with the top of the post behind her included in the picture. Maybe a bit more included out to the left as well, like a time-line that would fit your title. Lovely model.</td>', 'It''s a portrait to so great an extent as to detract from the effect of the rhythmic elements. I think I''d like to see her smaller for the context, with the top of the post behind her included in the picture. Maybe a bit more included out to the left as well, like a time-line that would fit your title. Lovely model.', '2006-05-03 06:05:05.000000', NULL, 1),
