INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2384474, 326943, 49578, '<td valign="top">That looks to be a good amount of effort!<br/>Nice vibrant hues!</td>', 'That looks to be a good amount of effort!Nice vibrant hues!', '2006-05-05 05:55:38.000000', NULL, 1),
(2384479, 329350, 49578, '<td valign="top">I would have liked it better if the subject would have stood out from the background.</td>', 'I would have liked it better if the subject would have stood out from the background.', '2006-05-05 05:58:55.000000', NULL, 1),
(2384481, 329073, 49578, '<td valign="top">nice perspective, and I love the border!</td>', 'nice perspective, and I love the border!', '2006-05-05 06:01:13.000000', NULL, 1),
(2384485, 329072, 49578, '<td valign="top">That is a lovely capture. I like the leading diagonal line and the expressions on the faces of the girls</td>', 'That is a lovely capture. I like the leading diagonal line and the expressions on the faces of the girls', '2006-05-05 06:05:01.000000', NULL, 1),
(2384490, 327357, 49578, '<td valign="top">the photo satisfies Rhythm, but to me it lacks a subject, and i am not too comfortable with the graduated tinting</td>', 'the photo satisfies Rhythm, but to me it lacks a subject, and i am not too comfortable with the graduated tinting', '2006-05-05 06:09:40.000000', NULL, 1),
(2384504, 327710, 49578, '<td valign="top">a little less saturation for the colours would have worked better as per my taste</td>', 'a little less saturation for the colours would have worked better as per my taste', '2006-05-05 06:26:39.000000', NULL, 1),
(2384534, 328736, 37334, '<td valign="top">Nice depth of colour and reflection. I also like the composition - gives it a graphic quality.7</td>', 'Nice depth of colour and reflection. I also like the composition - gives it a graphic quality.7', '2006-05-05 07:27:46.000000', NULL, 1),
(2384542, 329181, 37334, '<td valign="top">I like this a lot! I wish there was more detail in the top half of the sanddollar, but this is basic editing, so it not always easy;)6</td>', 'I like this a lot! I wish there was more detail in the top half of the sanddollar, but this is basic editing, so it not always easy;)6', '2006-05-05 07:31:14.000000', NULL, 1),
(2384545, 327753, 37334, '<td valign="top">Nice texture and DOF.</td>', 'Nice texture and DOF.', '2006-05-05 07:32:31.000000', NULL, 1),
(2384548, 328735, 37334, '<td valign="top">Who would have thought something so mundane could look so good.</td>', 'Who would have thought something so mundane could look so good.', '2006-05-05 07:33:46.000000', NULL, 1),
(2384554, 328592, 50355, '<td valign="top">Kind of fuzzy</td>', 'Kind of fuzzy', '2006-05-05 07:37:32.000000', NULL, 1),
(2384565, 328685, 50355, '<td valign="top">I think if you worked with the contrast it may have been better.</td>', 'I think if you worked with the contrast it may have been better.', '2006-05-05 07:42:15.000000', NULL, 1),
(2384567, 329353, 37334, '<td valign="top">Like a Monet painting! I like the surreal quality. Actually the more I look at it the more I like it!!10</td>', 'Like a Monet painting! I like the surreal quality. Actually the more I look at it the more I like it!!10', '2006-05-05 07:42:52.000000', NULL, 1),
(2384568, 329150, 50355, '<td valign="top">Just a bit bright, but good picture though.</td>', 'Just a bit bright, but good picture though.', '2006-05-05 07:43:46.000000', NULL, 1),
(2384572, 329304, 37334, '<td valign="top">I like the bold colours and reflection. I might have cropped it below the wondows as they spoil the pattern a little. Still like it though.</td>', 'I like the bold colours and reflection. I might have cropped it below the wondows as they spoil the pattern a little. Still like it though.', '2006-05-05 07:45:56.000000', NULL, 1),
