(2393127, 328694, 52296, '<td valign="top">Supernice, well done!</td>', 'Supernice, well done!', '2006-05-08 12:10:26.000000', NULL, 1),
(2393128, 329404, 8367, '<td valign="top">Nice colors and abstract. I don''t agree with your title, though. The smoothness is soothing but what you''ve portrayed is turbulent. JMHO</td>', 'Nice colors and abstract. I don''t agree with your title, though. The smoothness is soothing but what you''ve portrayed is turbulent. JMHO', '2006-05-08 12:10:51.000000', NULL, 1),
