(2396975, 329066, 58682, '<td valign="top">intresting concept. The challenge of Rhythm might have been better expressed either w/o the crease in the fabric or with one rose in each section. IMHO the crease breaks up the rhythm here.</td>', 'intresting concept. The challenge of Rhythm might have been better expressed either w/o the crease in the fabric or with one rose in each section. IMHO the crease breaks up the rhythm here.', '2006-05-09 13:03:04.000000', NULL, 1),
(2396978, 328168, 58682, '<td valign="top">I like the seperation of color here between the grass and the asphalt. The row of benches nicely draws the eye across the frame as well.</td>', 'I like the seperation of color here between the grass and the asphalt. The row of benches nicely draws the eye across the frame as well.', '2006-05-09 13:04:34.000000', NULL, 1),
(2396985, 327076, 58682, '<td valign="top">very nice! I really like your enterpreutation of rhythm here. The light on the left hand side is a little over exposed thoughcreating an almost blurry effect. Also the composition doesn''t particularly appeal to me. your seperation of patterns isn''t really in the middle but it''s not in thirds either.</td>', 'very nice! I really like your enterpreutation of rhythm here. The light on the left hand side is a little over exposed thoughcreating an almost blurry effect. Also the composition doesn''t particularly appeal to me. your seperation of patterns isn''t really in the middle but it''s not in thirds either.', '2006-05-09 13:06:49.000000', NULL, 1),
(2397010, 328644, 53964, '<td valign="top">Great DOF and lighting. You''ve captured the detail without blowing any highlights, and the background and crop compliment this perfectly.</td>', 'Great DOF and lighting. You''ve captured the detail without blowing any highlights, and the background and crop compliment this perfectly.', '2006-05-09 13:20:33.000000', NULL, 1),
(2397011, 328860, 50126, '<td valign="top">Nicely seen and executed. Great abstract.</td>', 'Nicely seen and executed. Great abstract.', '2006-05-09 13:20:37.000000', NULL, 1),
(2397012, 327783, 53964, '<td valign="top">I love this as a general image, but don''t get quite as much a rhythm flow as from some of the others. I can definitly see it postersized, tho!</td>', 'I love this as a general image, but don''t get quite as much a rhythm flow as from some of the others. I can definitly see it postersized, tho!', '2006-05-09 13:20:41.000000', NULL, 1),
(2397013, 329148, 53964, '<td valign="top">I love the simplicity of this. It''s amazingly effective.</td>', 'I love the simplicity of this. It''s amazingly effective.', '2006-05-09 13:20:52.000000', NULL, 1),
(2397070, 328722, 58682, '<td valign="top">The mountains in this shot are lovely, but the yellowed grass foreground detracts from them. I dont think it adds anything to the theme of "rhythm" either.</td>', 'The mountains in this shot are lovely, but the yellowed grass foreground detracts from them. I dont think it adds anything to the theme of "rhythm" either.', '2006-05-09 13:57:53.000000', NULL, 1),
(2397075, 329099, 58682, '<td valign="top">The theme of "rhythm" is very clear in this shot, well done. The light spot is a little over exposed and IMHO a wider DOF making a crisp orange edge would have been a little nicer.</td>', 'The theme of "rhythm" is very clear in this shot, well done. The light spot is a little over exposed and IMHO a wider DOF making a crisp orange edge would have been a little nicer.', '2006-05-09 14:00:13.000000', NULL, 1);
