(2397396, 328644, 58682, '<td valign="top">interesting choice of subject, but something is off... could the DOF have been wider, or may be it''s a little over exposed. the picture seems overly fuzzy to me, but then maybe that''s what you were going for.</td>', 'interesting choice of subject, but something is off... could the DOF have been wider, or may be it''s a little over exposed. the picture seems overly fuzzy to me, but then maybe that''s what you were going for.', '2006-05-09 15:30:08.000000', NULL, 1),
(2397403, 326793, 36060, '<td valign="top">Very interesting shot!</td>', 'Very interesting shot!', '2006-05-09 15:33:56.000000', NULL, 1),
