(2399394, 326943, 52549, '<td valign="top">Congratulations on this well deserved blue. Excellent picture.</td>', 'Congratulations on this well deserved blue. Excellent picture.', '2006-05-10 02:11:19.000000', NULL, 0),
(2399396, 328845, 15711, '<td valign="top">Congrats!  I missed voting on alot of these. This surely slipped by me. The movement at the bottom and focus at the top is pretty darn clever.  Bravo.</td>', 'Congrats!  I missed voting on alot of these. This surely slipped by me. The movement at the bottom and focus at the top is pretty darn clever.  Bravo.', '2006-05-10 02:11:41.000000', NULL, 0),
