INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3287942, 329005, 72581, '<td valign="top">I love the color!</td>', 'I love the color!', '2007-01-26 16:45:39.000000', NULL, 0),
(3490696, 329005, 52992, '<td valign="top">So bright - I love it.</td>', 'So bright - I love it.', '2007-03-27 09:01:54.000000', NULL, 0),
(3499609, 329319, 73305, '<td valign="top">What were the settings you used?  I have the same camera and tried for hours to capture smoke and couldn''t.  This looks great! :)</td>', 'What were the settings you used?  I have the same camera and tried for hours to capture smoke and couldn''t.  This looks great! :)', '2007-03-30 12:22:03.000000', NULL, 0),
(3782344, 329005, 74078, '<td valign="top">Basic image yet so very eye catching and effective. Not sure what the background that was used it, but IMO this image could only <br/>be done better if it were a clean black background. I think that some attention is taken away from the pencils by the stripes in the background, but hey, it caught my eye as soon as I entered your folio.</td>', 'Basic image yet so very eye catching and effective. Not sure what the background that was used it, but IMO this image could only be done better if it were a clean black background. I think that some attention is taken away from the pencils by the stripes in the background, but hey, it caught my eye as soon as I entered your folio.', '2007-06-14 08:06:37.000000', NULL, 0),
(3831060, 329393, 48228, '<td valign="top">quite eerie but ever so dam good.....</td>', 'quite eerie but ever so dam good.....', '2007-06-25 09:26:20.000000', NULL, 0),
(3906892, 329372, 5112, '<td valign="top">I just love this image!</td>', 'I just love this image!', '2007-07-16 02:43:27.000000', NULL, 0),
(3911991, 328785, 66384, '<td valign="top">Amazing how you made dirt so beautiful. The rich tones, and beautiful lighting and composition make this a work of art.</td>', 'Amazing how you made dirt so beautiful. The rich tones, and beautiful lighting and composition make this a work of art.', '2007-07-17 23:38:24.000000', NULL, 0),
(3930403, 329005, 80278, '<td valign="top">Congratulations Sherryl! I found this image while researching for an entry into Rhythm III. <br/>I am surprised that no one mentioned the incredible illusion of DOF that you created by using only color. To my eye, that is what makes your image so appealing. I also think your background texture is an enhancement, not a detraction as some below have commented.  On my monitor at least, it is a subtle texture that acts as a complementary foil for the foreground. It establishes a rectilinear tableau as a reference for the wave. This is a 10 in my book!</td>', 'Congratulations Sherryl! I found this image while researching for an entry into Rhythm III. I am surprised that no one mentioned the incredible illusion of DOF that you created by using only color. To my eye, that is what makes your image so appealing. I also think your background texture is an enhancement, not a detraction as some below have commented.  On my monitor at least, it is a subtle texture that acts as a complementary foil for the foreground. It establishes a rectilinear tableau as a reference for the wave. This is a 10 in my book!', '2007-07-23 23:36:58.000000', NULL, 0),
(3932634, 329353, 79604, '<td valign="top">Can''t believe so many voted this so low. I have yet to understand the voting at DPC! Congratulations on your Red Ribbon.</td>', 'Can''t believe so many voted this so low. I have yet to understand the voting at DPC! Congratulations on your Red Ribbon.', '2007-07-24 17:32:01.000000', NULL, 0),
(3967515, 329005, 53278, '<td valign="top">when the last rythm challenge came up i immediatly came to your page to look at this pic, first i though i could reproduce it , but then i realized how tough it was.<br/>great job!</td>', 'when the last rythm challenge came up i immediatly came to your page to look at this pic, first i though i could reproduce it , but then i realized how tough it was.great job!', '2007-08-04 00:45:41.000000', NULL, 0),
